  cmd: "python3 -c 'import csv,datetime,collections,json,pathlib; p=pathlib.Path("feedback.csv"); rows=list(csv.DictReader(p.open(encoding="utf-8"))); sessions=list(csv.DictReader(open("sessions.csv",encoding="utf-8"))); valid_sessions={x["session_id"] for x in sessions}; cols=rows[0].keys(); print(json.dumps({"rows":len(rows),"columns":list(cols),"session_rows":len(sessions),"session_ids":sorted(valid_sessions)},ensure_ascii=False)); reasons=collections.Counter(); event_groups=collections.defaultdict(list); participant_session=collections.defaultdict(list); valid=[]; invalid=[];
for r in rows:
    errs=[]
    if r["session_id"] not in valid_sessions: errs.append("unknown_session")
    if not r["participant_id"]: errs.append("missing_participant")
    try:
      s=int(r["score"])
      if not 1<=s<=5: errs.append("score_out_of_range")
    except: errs.append("score_not_integer")
    if r["has_issue"] not in ("true","false"): errs.append("has_issue_invalid")
    try: datetime.datetime.fromisoformat(r["submitted_at"].replace("Z","+00:00"))
    except: errs.append("submitted_at_invalid")
    event_groups[r["event_id"]].append(r); participant_session[(r["participant_id"],r["session_id"])].append(r)
    (invalid if errs else valid).append((r,errs)); [reasons.__setitem__(e,reasons[e]+1) for e in errs]
print("invalid",len(invalid),"valid",len(valid),"reason_counts",dict(reasons));
for eid,grp in event_groups.items():
  sigs={tuple(r[c] for c in cols if c not in ("row_id","event_id")) for r in grp};
  if len(grp)>1: print("event",eid,"rows",[r["row_id"] for r in grp],"signatures",len(sigs))
for key,grp in participant_session.items():
  if len(grp)>1: print("participant_session",key,"rows",[r["row_id"] for r in grp],"times",[r["submitted_at"] for r in grp])
print("invalid_rows",[(r["row_id"],e) for r,e in invalid]);
print("valid_by_session",collections.Counter(r["session_id"] for r,e in valid));
# apply conservative valid latest per participant/session, exact retry collapse by event signature, excluding event conflicts
usable=[]; rejected=[]
for r,e in invalid: rejected.append((r["row_id"],";".join(e)))
for eid,grp in event_groups.items():
  sigs={tuple(r[c] for c in cols if c not in ("row_id","event_id")) for r in grp}
  if len(sigs)>1:
    for r in grp: rejected.append((r["row_id"],"event_conflict"))
  else:
    usable.append(grp[0])
byps=collections.defaultdict(list)
for r in usable: byps[(r["participant_id"],r["session_id"])].append(r)
final=[]
for k,grp in byps.items():
  if len(grp)>1:
    # deterministic latest timestamp then row id tie breaker
    grp=sorted(grp,key=lambda r:(datetime.datetime.fromisoformat(r["submitted_at"].replace("Z","+00:00")),r["row_id"]))
    final.append(grp[-1])
    for old in grp[:-1]: rejected.append((old["row_id"],"superseded_by_latest"))
  else: final.extend(grp)
print("final",len(final),"final_rows",[r["row_id"] for r in sorted(final,key=lambda r:r["row_id"])])
print("rejected",sorted(rejected)); print("summary");
for sid in sorted(valid_sessions):
  g=[r for r in final if r["session_id"]==sid]; n=len(g); avg=round(sum(int(r["score"]) for r in g)/n,2) if n>=3 else None; rate=round(sum(r["has_issue"]=="true" for r in g)/n,2) if n>=3 else None; print(sid,n,avg,rate,[r["row_id"] for r in g])' ",
